// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 g) public {
        vm.assume(actor != address(0) && actor != address(c));

        // lock in a guess for block 101
        vm.roll(100);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bytes32(g));

        // move past the target block and compute the real answer
        vm.roll(102);
        bytes32 ans = blockhash(101);
        // make sure the guess is wrong so settle() never attempts the 2-ether payout
        vm.assume(bytes32(g) != ans);

        vm.prank(actor);
        c.settle();

        // RULE: after settle() completes, the sender's guess slot is free,
        // so lockInGuess must be possible again.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(bytes32(g)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
